const ops = game.modules.get("dg-ops")?.api;
if (!ops) return ui.notifications.warn("Delta Green: Ops Automation isn't active.");
if (!game.user.isGM) return ui.notifications.warn("That one is for the Handler.");
const sel = ops.selected();
if (sel.length !== 1) return ui.notifications.warn("Select one Agent's token.");
await ops.editSanLog(sel[0]);
